"use client"

import "@vidstack/react/player/styles/default/theme.css"
import "@vidstack/react/player/styles/default/layouts/audio.css"

import {
  MediaPlayer,
  type MediaPlayerInstance,
  type MediaPlayerProps,
  MediaProvider,
} from "@vidstack/react"
import {
  DefaultAudioLayout,
  type DefaultLayoutTranslations,
  defaultLayoutIcons,
} from "@vidstack/react/player/layouts/default"
import { forwardRef } from "react"

export interface CursareAudioPlayerProps
  extends Omit<MediaPlayerProps, "ariaLabel" | "children" | "src" | "title"> {
  ariaLabel?: string
  src: string
  title: string
  translations?: DefaultLayoutTranslations
}

export const CursareAudioPlayer = forwardRef<MediaPlayerInstance, CursareAudioPlayerProps>(
  function CursareAudioPlayer(
    {
      ariaLabel,
      autoPlay = false,
      load = "visible",
      preload = "metadata",
      src,
      storage = null,
      streamType = "on-demand",
      title,
      translations,
      viewType = "audio",
      ...props
    },
    ref,
  ) {
    return (
      <MediaPlayer
        {...props}
        ref={ref}
        src={src}
        title={title}
        ariaLabel={ariaLabel ?? title}
        viewType={viewType}
        streamType={streamType}
        load={load}
        preload={preload}
        autoPlay={autoPlay}
        storage={storage}
      >
        <MediaProvider />
        <DefaultAudioLayout
          icons={defaultLayoutIcons}
          translations={translations}
          noKeyboardAnimations
          slots={{ airPlayButton: null, googleCastButton: null }}
        />
      </MediaPlayer>
    )
  },
)

import type { VideoProvider } from "@/components/cursare/foundation/model/learner-runtime"
import type { PlayerSrc } from "@vidstack/react"

export function videoPlayerSource(provider: VideoProvider, src: string): PlayerSrc {
  if (provider === "youtube") return { src, type: "video/youtube" }
  if (provider === "vimeo") return { src, type: "video/vimeo" }
  if (provider === "hls") return { src, type: "application/x-mpegurl" }
  return src
}

"use client"

import "@vidstack/react/player/styles/default/theme.css"
import "@vidstack/react/player/styles/default/layouts/video.css"

import type { VideoProvider, VideoTextTrack } from "@/components/cursare/foundation/model/learner-runtime"
import {
  MediaPlayer,
  type MediaPlayerInstance,
  type MediaPlayerProps,
  MediaProvider,
  Track,
} from "@vidstack/react"
import {
  type DefaultLayoutTranslations,
  DefaultVideoLayout,
  defaultLayoutIcons,
} from "@vidstack/react/player/layouts/default"
import { forwardRef } from "react"
import { videoPlayerSource } from "./source"

export interface CursareVideoPlayerProps
  extends Omit<MediaPlayerProps, "ariaLabel" | "children" | "src" | "title"> {
  ariaLabel?: string
  provider: VideoProvider
  src: string
  title: string
  tracks?: readonly VideoTextTrack[]
  translations?: DefaultLayoutTranslations
}

export const CursareVideoPlayer = forwardRef<MediaPlayerInstance, CursareVideoPlayerProps>(
  function CursareVideoPlayer(
    {
      ariaLabel,
      autoPlay = false,
      load = "visible",
      playsInline = true,
      posterLoad = "visible",
      preload = "metadata",
      provider,
      src,
      storage = null,
      streamType = "on-demand",
      title,
      tracks = [],
      translations,
      viewType = "video",
      ...props
    },
    ref,
  ) {
    return (
      <MediaPlayer
        {...props}
        ref={ref}
        src={videoPlayerSource(provider, src)}
        title={title}
        ariaLabel={ariaLabel ?? title}
        viewType={viewType}
        streamType={streamType}
        load={load}
        posterLoad={posterLoad}
        preload={preload}
        playsInline={playsInline}
        autoPlay={autoPlay}
        storage={storage}
      >
        <MediaProvider>
          {tracks.map((track) => (
            <Track
              key={`${track.kind}:${track.lang}:${track.src}`}
              src={track.src}
              kind={track.kind}
              label={track.label}
              lang={track.lang}
              default={track.default}
            />
          ))}
        </MediaProvider>
        <DefaultVideoLayout
          icons={defaultLayoutIcons}
          translations={translations}
          noKeyboardAnimations
          slots={{ airPlayButton: null, googleCastButton: null, pipButton: null }}
        />
      </MediaPlayer>
    )
  },
)

"use client"

import {
  type LearnerAnchor,
  learnerAnchors,
  type ParsedContentDocument,
} from "@/components/cursare/foundation/model/learner-runtime"
import {
  createVideoPlaybackService,
  type EditorMessages,
  type LearnerActivityReport,
  LearnerButton,
  type PollLoad,
  type PollVote,
  type QuizGrade,
  type ReferenceSearch,
  type SavedQuiz,
} from "@/components/cursare/composer/viewer"
import { MessageSquarePlus } from "lucide-react"
import {
  type CSSProperties,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react"
import { DirectDocumentRenderer, type DirectReaderServices } from "./document-renderer"
import { learnerAnchorDomTargets } from "./learner-note-dom"

export interface LearnerNoteAnchorContext {
  anchorId: string
  blockType: string
  label: string
  sectionId: string | null
  sectionLabel: string | null
  noteCount: number
}

export interface LearnerNoteCreationRequest extends LearnerNoteAnchorContext {
  videoSeconds: number | null
}

export interface LearnerNoteNavigationTarget {
  key: string
  anchorId: string
  videoSeconds?: number | null
}

export interface LearnerNotesBridge {
  counts?: Readonly<Record<string, number>>
  createLabel: (context: LearnerNoteAnchorContext) => string
  countLabel: (count: number, context: LearnerNoteAnchorContext) => string
  onCreateRequest: (request: LearnerNoteCreationRequest) => void
  onActiveAnchorChange?: (context: LearnerNoteAnchorContext | null) => void
  navigationTarget?: LearnerNoteNavigationTarget | null
  onNavigationComplete?: (target: LearnerNoteNavigationTarget, found: boolean) => void
  setPlaybackTimeResolver?: (
    resolver: ((anchorId: string) => Promise<number | null>) | null,
  ) => void
}

interface AnchorPlacement {
  context: LearnerNoteAnchorContext
  top: number
}

export interface ContentReaderProps {
  content: ParsedContentDocument
  referenceProvider?: ReferenceSearch
  referenceBase?: string | null
  referenceNavigationEnabled?: boolean
  completedReferenceKeys?: string[]
  unavailableReferenceKeys?: string[]
  onGradeQuiz?: QuizGrade
  savedQuiz?: SavedQuiz | null
  onPollVote?: PollVote
  onPollLoad?: PollLoad
  messages?: EditorMessages
  learnerNotes?: LearnerNotesBridge
  onLearnerActivity?: LearnerActivityReport
}

export function ContentReader({
  content,
  referenceProvider,
  referenceBase,
  referenceNavigationEnabled,
  completedReferenceKeys,
  unavailableReferenceKeys,
  onGradeQuiz,
  savedQuiz,
  onPollVote,
  onPollLoad,
  messages,
  learnerNotes,
  onLearnerActivity,
}: ContentReaderProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const actionRefs = useRef(new Map<string, HTMLButtonElement>())
  const [placements, setPlacements] = useState<AnchorPlacement[]>([])
  const anchors = useMemo(() => learnerAnchors(content), [content])
  const playback = useMemo(createVideoPlaybackService, [])
  const sectionByAnchor = useMemo(
    () => new Map(anchors.map((anchor) => [anchor.id, anchor.sectionId])),
    [anchors],
  )
  const services = useMemo<DirectReaderServices>(
    () => ({
      messages,
      referenceProvider,
      referenceBase,
      referenceNavigationEnabled,
      completedReferenceKeys,
      unavailableReferenceKeys,
      onGradeQuiz,
      savedQuiz,
      onPollVote,
      onPollLoad,
      onLearnerActivity,
      playback,
      sectionByAnchor,
    }),
    [
      completedReferenceKeys,
      messages,
      onGradeQuiz,
      onLearnerActivity,
      onPollLoad,
      onPollVote,
      playback,
      referenceBase,
      referenceNavigationEnabled,
      referenceProvider,
      savedQuiz,
      sectionByAnchor,
      unavailableReferenceKeys,
    ],
  )

  useEffect(() => {
    if (!learnerNotes?.setPlaybackTimeResolver) return
    learnerNotes.setPlaybackTimeResolver((anchorId) => playback.currentTime(anchorId))
    return () => learnerNotes.setPlaybackTimeResolver?.(null)
  }, [learnerNotes?.setPlaybackTimeResolver, playback])

  const contextFor = useCallback(
    (anchor: LearnerAnchor): LearnerNoteAnchorContext => ({
      anchorId: anchor.id,
      blockType: anchor.nodeType,
      label: anchor.label,
      sectionId: anchor.sectionId,
      sectionLabel: anchor.sectionLabel,
      noteCount: learnerNotes?.counts?.[anchor.id] ?? 0,
    }),
    [learnerNotes?.counts],
  )

  useLayoutEffect(() => {
    if (!learnerNotes || !rootRef.current) {
      setPlacements([])
      return
    }
    const root = rootRef.current
    let frame = 0
    const measure = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() => {
        const rootRect = root.getBoundingClientRect()
        const next = learnerAnchorDomTargets(root, anchors).map(({ anchor, element }) => {
          const rect = element.getBoundingClientRect()
          return {
            context: contextFor(anchor),
            top: rect.top - rootRect.top + Math.min(8, Math.max(0, rect.height / 2 - 16)),
          }
        })
        setPlacements(next)
      })
    }
    const observer = new ResizeObserver(measure)
    observer.observe(root)
    for (const { element } of learnerAnchorDomTargets(root, anchors)) observer.observe(element)
    window.addEventListener("resize", measure)
    measure()
    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
      window.removeEventListener("resize", measure)
    }
  }, [anchors, contextFor, learnerNotes])

  useEffect(() => {
    if (!learnerNotes?.onActiveAnchorChange || !rootRef.current || placements.length === 0) return
    const root = rootRef.current
    let frame = 0
    let lastId: string | null = null
    const report = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() => {
        const threshold = 128
        const targets = learnerAnchorDomTargets(root, anchors)
        const current =
          [...targets]
            .reverse()
            .find(({ element }) => element.getBoundingClientRect().top <= threshold) ?? targets[0]
        const id = current?.anchor.id ?? null
        if (id === lastId) return
        lastId = id
        learnerNotes.onActiveAnchorChange?.(current ? contextFor(current.anchor) : null)
      })
    }
    document.addEventListener("scroll", report, { passive: true, capture: true })
    report()
    return () => {
      cancelAnimationFrame(frame)
      document.removeEventListener("scroll", report, { capture: true })
    }
  }, [anchors, contextFor, learnerNotes, placements.length])

  useEffect(() => {
    const target = learnerNotes?.navigationTarget
    const root = rootRef.current
    if (!target || !root) return
    let cancelled = false
    let frame = 0
    let attempts = 0
    const locate = () => {
      if (cancelled) return
      const match = learnerAnchorDomTargets(root, anchors).find(
        ({ anchor }) => anchor.id === target.anchorId,
      )
      if (!match && attempts < 30) {
        attempts += 1
        frame = requestAnimationFrame(locate)
        return
      }
      if (!match) {
        learnerNotes.onNavigationComplete?.(target, false)
        return
      }
      match.element.scrollIntoView({ behavior: "smooth", block: "center" })
      const complete = async () => {
        if (typeof target.videoSeconds === "number") {
          await playback.seek(target.anchorId, target.videoSeconds)
        }
        window.setTimeout(() => {
          if (cancelled) return
          actionRefs.current.get(target.anchorId)?.focus({ preventScroll: true })
          learnerNotes.onNavigationComplete?.(target, true)
        }, 320)
      }
      void complete()
    }
    locate()
    return () => {
      cancelled = true
      cancelAnimationFrame(frame)
    }
  }, [anchors, learnerNotes?.navigationTarget, learnerNotes?.onNavigationComplete, playback])

  const createNote = async (context: LearnerNoteAnchorContext) => {
    const videoSeconds =
      context.blockType === "video" ? await playback.currentTime(context.anchorId) : null
    learnerNotes?.onCreateRequest({ ...context, videoSeconds })
  }

  return (
    <div
      ref={rootRef}
      className="content-editor"
      data-mode="reader"
      data-learner-notes={learnerNotes ? "enabled" : undefined}
    >
      <DirectDocumentRenderer document={content} services={services} />
      {learnerNotes ? (
        <div className="content-note-actions" aria-hidden="false">
          {placements.map(({ context, top }) => {
            const countLabel = learnerNotes.countLabel(context.noteCount, context)
            const createLabel = learnerNotes.createLabel(context)
            return (
              <LearnerButton
                key={context.anchorId}
                ref={(element) => {
                  if (element) actionRefs.current.set(context.anchorId, element)
                  else actionRefs.current.delete(context.anchorId)
                }}
                type="button"
                variant="ghost"
                className="content-note-action"
                data-learner-effect="focus"
                data-has-notes={context.noteCount > 0 ? "true" : undefined}
                style={
                  {
                    "--learner-note-top": `${top}px`,
                  } as CSSProperties
                }
                aria-label={context.noteCount > 0 ? `${createLabel}. ${countLabel}` : createLabel}
                title={createLabel}
                onClick={() => void createNote(context)}
              >
                <MessageSquarePlus aria-hidden="true" />
                {context.noteCount > 0 ? (
                  <span className="content-note-count" aria-hidden="true">
                    {context.noteCount > 99 ? "99+" : context.noteCount}
                  </span>
                ) : null}
              </LearnerButton>
            )
          })}
        </div>
      ) : null}
    </div>
  )
}

import type { LearnerAnchor } from "@/components/cursare/foundation/model/learner-runtime"

// Never mutates the reader's rendered content.
export function learnerAnchorDomTargets(
  root: Pick<ParentNode, "querySelector">,
  anchors: readonly LearnerAnchor[],
): Array<{ anchor: LearnerAnchor; element: HTMLElement }> {
  return anchors.flatMap((anchor) => {
    const escaped = anchor.id.replaceAll("\\", "\\\\").replaceAll('"', '\\"')
    const element = root.querySelector(`[data-learner-anchor-id="${escaped}"]`)
    return element ? [{ anchor, element: element as HTMLElement }] : []
  })
}

import { CODE_LANGUAGES, normalizeCodeLanguage } from "@/components/cursare/foundation/model/learner-runtime"
import Prism from "prismjs"
import "prismjs/components/prism-bash"
import "prismjs/components/prism-c"
import "prismjs/components/prism-cpp"
import "prismjs/components/prism-csharp"
import "prismjs/components/prism-docker"
import "prismjs/components/prism-go"
import "prismjs/components/prism-graphql"
import "prismjs/components/prism-java"
import "prismjs/components/prism-json"
import "prismjs/components/prism-kotlin"
import "prismjs/components/prism-markdown"
import "prismjs/components/prism-markup-templating"
import "prismjs/components/prism-php"
import "prismjs/components/prism-python"
import "prismjs/components/prism-ruby"
import "prismjs/components/prism-rust"
import "prismjs/components/prism-scss"
import "prismjs/components/prism-sql"
import "prismjs/components/prism-swift"
import "prismjs/components/prism-typescript"
import "prismjs/components/prism-jsx"
import "prismjs/components/prism-tsx"
import "prismjs/components/prism-yaml"
import type { HighlightedCode, SyntaxHighlighter, SyntaxToken } from "./syntax-highlighter"

// Tokens are rendered by the host, so Prism v1's browser auto-run must not touch
// the source DOM.
Prism.manual = true

const languages = CODE_LANGUAGES

function inferredLanguage(code: string) {
  const source = code.trim()
  if (!source) return "plaintext"

  if (/^#!.*\b(?:ba|z)?sh\b/m.test(source)) return "bash"
  if (/^(?:FROM|RUN|COPY|ADD|WORKDIR|ENTRYPOINT|CMD|EXPOSE|ENV)\b/m.test(source)) return "docker"

  if (/^[{[]/.test(source)) {
    try {
      JSON.parse(source)
      return "json"
    } catch {}
  }

  if (/^<\/?[a-z][\s\S]*>/i.test(source)) return "markup"
  if (/^(?:query|mutation|subscription|fragment)\b/m.test(source)) return "graphql"
  if (/^(?:SELECT|WITH|INSERT|UPDATE|DELETE|CREATE|ALTER|DROP)\b/im.test(source)) return "sql"
  if (/^(?:package\s+main|func\s+\w+\s*\()/m.test(source)) return "go"
  if (/^(?:fn\s+\w+|let\s+mut\b|impl\s+\w+|use\s+\w+::)|println!/m.test(source)) return "rust"
  if (/^(?:def\s+\w+|from\s+\S+\s+import\b|class\s+\w+.*:|print\s*\()/m.test(source)) {
    return "python"
  }
  if (/^(?:\$\s*)?(?:bun|npm|npx|pnpm|yarn|git|curl|docker|cd|mkdir|export)\b/m.test(source)) {
    return "bash"
  }
  if (
    /\b(?:interface|enum|namespace)\s+\w+|\bimport\s+type\b|\bas\s+const\b|:\s*(?:string|number|boolean)\b/.test(
      source,
    )
  ) {
    return "typescript"
  }
  if (
    /\b(?:const|let|var|function|class|import|export|await)\b|\b(?:if|for|while|switch|catch)\s*\(|=>|===|!==|\?\.|\bBun\./.test(
      source,
    )
  ) {
    return "javascript"
  }
  if (/^[^{\n]+\{[\s\S]*\b[-a-z]+\s*:\s*[^;{}]+;/im.test(source)) return "css"
  if (/^(?:---\s*$|[\w.-]+:\s+\S+)/m.test(source)) return "yaml"

  return "plaintext"
}

function tokenLength(token: string | Prism.Token | Array<string | Prism.Token>): number {
  if (typeof token === "string") return token.length
  if (Array.isArray(token)) return token.reduce((length, child) => length + tokenLength(child), 0)
  return tokenLength(token.content)
}

function appendTokens(
  stream: string | Prism.Token | Array<string | Prism.Token>,
  offset: number,
  inheritedClasses: string[],
  tokens: SyntaxToken[],
): number {
  if (typeof stream === "string") {
    const to = offset + stream.length
    if (stream.length > 0 && inheritedClasses.length > 0) {
      tokens.push({
        from: offset,
        to,
        className: `token ${[...new Set(inheritedClasses)].join(" ")}`,
      })
    }
    return to
  }

  if (Array.isArray(stream)) {
    return stream.reduce(
      (position, child) => appendTokens(child, position, inheritedClasses, tokens),
      offset,
    )
  }

  const aliases = Array.isArray(stream.alias) ? stream.alias : stream.alias ? [stream.alias] : []
  const classes = [...inheritedClasses, stream.type, ...aliases]
  const end = appendTokens(stream.content, offset, classes, tokens)

  // Some third-party grammars emit a content stream that doesn't reproduce the
  // matched source length.
  return Math.max(end, offset + tokenLength(stream.content))
}

function addBashCommandTokens(code: string, tokens: SyntaxToken[]) {
  for (const match of code.matchAll(/(^|\n)([\t ]*(?:\$[\t ]*)?)([a-zA-Z_][\w.-]*)/g)) {
    const command = match[3]
    if (!command || match.index === undefined) continue
    const from = match.index + (match[1]?.length ?? 0) + (match[2]?.length ?? 0)
    const to = from + command.length
    if (tokens.some((token) => token.from < to && token.to > from)) continue
    tokens.push({ from, to, className: "token function" })
  }
  tokens.sort((left, right) => left.from - right.from)
}

function tokenize(code: string, language: unknown): HighlightedCode {
  const explicit = typeof language === "string" && language.trim().length > 0
  const normalized = explicit ? normalizeCodeLanguage(language) : inferredLanguage(code)
  const descriptor = languages.find(({ value }) => value === normalized) ?? CODE_LANGUAGES[0]
  const grammar = Prism.languages[normalized]
  if (!grammar || normalized === "plaintext" || code.length === 0) {
    return { language: normalized, label: descriptor.label, tokens: [] }
  }

  const tokens: SyntaxToken[] = []
  appendTokens(Prism.tokenize(code, grammar), 0, [], tokens)
  if (normalized === "bash") addBashCommandTokens(code, tokens)
  return { language: normalized, label: descriptor.label, tokens }
}

export const prismHighlighter: SyntaxHighlighter = {
  languages,
  normalizeLanguage: normalizeCodeLanguage,
  tokenize,
}

import type { CodeLanguage } from "@/components/cursare/foundation/model/learner-runtime"
import { prismHighlighter } from "./prism"

export type SyntaxLanguage = CodeLanguage

export interface SyntaxToken {
  from: number
  to: number
  className: string
}

export interface HighlightedCode {
  language: string
  label: string
  tokens: SyntaxToken[]
}

// The only contract the editor has with a highlighting engine. Tokens are
// transient presentation tokens and never enter the saved document.
export interface SyntaxHighlighter {
  languages: readonly SyntaxLanguage[]
  normalizeLanguage(language: unknown): string
  tokenize(code: string, language: unknown): HighlightedCode
}

// Swapping engines changes this binding and nothing else.
export const syntaxHighlighter: SyntaxHighlighter = prismHighlighter

"use client"

import {
  CursareVideoPlayer,
  type DefaultLayoutTranslations,
  type MediaPlayerInstance,
  type MediaTimeUpdateEvent,
} from "@/components/cursare/composer/media"
import type { VideoProvider, VideoTextTrack } from "@/components/cursare/foundation/model/learner-runtime"
import { Button } from "@/components/cursare/ui/button"
import { Input } from "@/components/cursare/ui/input"
import { type KeyboardEvent, useEffect, useId, useMemo, useRef, useState } from "react"
import type { VideoPlaybackHandle } from "./contracts"
import { LearnerVisuallyHidden } from "./learner-primitives"
import { reachedVideoMilestones } from "./video-milestones"
import {
  continueVideoPlayback,
  formatVideoTime,
  parseVideoResume,
  videoResumeStorageKey,
} from "./video-resume"
import { videoShortcutAction } from "./video-shortcuts"
import { filterTranscriptCues, parseWebVtt, type TranscriptCue } from "./webvtt"

function controlledVideoPlaybackHandle(player: MediaPlayerInstance): VideoPlaybackHandle {
  let ready = player.state.canPlay
  let destroyed = false
  const waiters = new Set<(available: boolean) => void>()
  const resolveWaiters = (available: boolean) => {
    for (const resolve of waiters) resolve(available)
    waiters.clear()
  }
  return {
    capabilities: () => ({
      playPause: true,
      currentTime: player.state.canPlay,
      seek: player.state.canPlay && player.state.canSeek,
      duration:
        player.state.canPlay && Number.isFinite(player.state.duration) && player.state.duration > 0,
      playbackRate: player.state.canSetPlaybackRate,
      quality: player.state.canSetQuality && player.state.qualities.length > 0,
      fullscreen: player.state.canFullscreen,
      pictureInPicture: player.state.canPictureInPicture,
      events: { readiness: true, ended: true },
    }),
    ready: () => {
      if (destroyed) return
      ready = true
      resolveWaiters(true)
    },
    currentTime: async () => {
      const value = player.currentTime
      return Number.isFinite(value) && value >= 0 ? value : null
    },
    seek: async (seconds) => {
      if (destroyed || !Number.isFinite(seconds) || seconds < 0) return false
      if (!ready && !player.state.canPlay) {
        const available = await new Promise<boolean>((resolve) => waiters.add(resolve))
        if (!available) return false
      }
      try {
        await player.pause()
        player.currentTime = seconds
        await player.pause()
        return true
      } catch {
        return false
      }
    },
    destroy: () => {
      if (destroyed) return
      destroyed = true
      resolveWaiters(false)
    },
  }
}

export interface AccessibleVideoPlayerProps {
  src: string
  provider: VideoProvider
  tracks: VideoTextTrack[]
  title: string
  loadingLabel: string
  failureLabel: string
  shortcutHelp: string
  resumeIdentity: string
  resumePrompt: (time: string) => string
  resumeAction: string
  startOver: string
  transcriptLabel: string
  transcriptSearchLabel: string
  transcriptEmptyLabel: string
  transcriptFailureLabel: string
  translations: DefaultLayoutTranslations
  onPlaybackHandle: (handle: VideoPlaybackHandle) => void
  onMilestone?: (percent: 0 | 25 | 50 | 75 | 100) => void
}

function applyShortcut(event: KeyboardEvent<HTMLElement>, player: MediaPlayerInstance) {
  const action = videoShortcutAction(event)
  if (!action) return
  event.preventDefault()

  if (action === "togglePaused") {
    void (player.state.paused ? player.play() : player.pause()).catch(() => undefined)
    return
  }
  if (action === "toggleMuted") {
    player.muted = !player.muted
    return
  }
  if (action === "seekBackward" || action === "seekForward") {
    if (!player.state.canSeek) return
    const offset = action === "seekBackward" ? -10 : 10
    const end = Number.isFinite(player.duration) && player.duration > 0 ? player.duration : Infinity
    player.currentTime = Math.min(end, Math.max(0, player.currentTime + offset))
    return
  }
  if (!player.state.canFullscreen) return
  void (player.state.fullscreen ? player.exitFullscreen() : player.enterFullscreen()).catch(
    () => undefined,
  )
}

// Learner-only, and loaded lazily.
export function AccessibleVideoPlayer({
  src,
  provider,
  tracks,
  title,
  loadingLabel,
  failureLabel,
  shortcutHelp,
  resumeIdentity,
  resumePrompt,
  resumeAction,
  startOver,
  transcriptLabel,
  transcriptSearchLabel,
  transcriptEmptyLabel,
  transcriptFailureLabel,
  translations,
  onPlaybackHandle,
  onMilestone,
}: AccessibleVideoPlayerProps) {
  const playerRef = useRef<MediaPlayerInstance>(null)
  const handleRef = useRef<VideoPlaybackHandle | null>(null)
  const lastStoredBucket = useRef(-1)
  const transcriptRequestRef = useRef<{ src: string; status: "loading" | "done" } | null>(null)
  const milestonesRef = useRef(new Set<number>())
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading")
  const [resumeSeconds, setResumeSeconds] = useState<number | null>(null)
  const [transcriptOpen, setTranscriptOpen] = useState(false)
  const [transcriptStatus, setTranscriptStatus] = useState<"idle" | "loading" | "ready" | "error">(
    "idle",
  )
  const [transcriptCues, setTranscriptCues] = useState<TranscriptCue[]>([])
  const [transcriptQuery, setTranscriptQuery] = useState("")
  const helpId = `video-shortcuts-${useId().replaceAll(":", "")}`
  const resumeKey = videoResumeStorageKey(resumeIdentity)
  const milestoneKey = `${resumeKey}:milestones`
  const transcriptTrack = tracks.find((track) => track.default) ?? tracks[0] ?? null
  const transcriptSrc = transcriptTrack?.src ?? null
  const visibleCues = useMemo(
    () => filterTranscriptCues(transcriptCues, transcriptQuery),
    [transcriptCues, transcriptQuery],
  )

  useEffect(() => {
    const player = playerRef.current
    if (!player) return
    const handle = controlledVideoPlaybackHandle(player)
    handleRef.current = handle
    onPlaybackHandle(handle)
    return () => {
      handle.destroy?.()
      if (handleRef.current === handle) handleRef.current = null
    }
  }, [onPlaybackHandle])

  useEffect(() => {
    const record = parseVideoResume(window.localStorage.getItem(resumeKey))
    if (!record) {
      window.localStorage.removeItem(resumeKey)
      return
    }
    setResumeSeconds(record.seconds)
  }, [resumeKey])

  useEffect(() => {
    try {
      const stored = JSON.parse(window.sessionStorage.getItem(milestoneKey) ?? "[]")
      if (Array.isArray(stored)) milestonesRef.current = new Set(stored.map(Number))
    } catch {
      try {
        window.sessionStorage.removeItem(milestoneKey)
      } catch {}
    }
  }, [milestoneKey])

  const emitMilestone = (percent: 0 | 25 | 50 | 75 | 100) => {
    if (milestonesRef.current.has(percent)) return
    milestonesRef.current.add(percent)
    try {
      window.sessionStorage.setItem(milestoneKey, JSON.stringify([...milestonesRef.current]))
    } catch {}
    onMilestone?.(percent)
  }

  useEffect(() => {
    if (!transcriptOpen || !transcriptSrc) return
    const existingRequest = transcriptRequestRef.current
    if (existingRequest?.src === transcriptSrc) return

    const controller = new AbortController()
    transcriptRequestRef.current = { src: transcriptSrc, status: "loading" }
    setTranscriptStatus("loading")
    fetch(transcriptSrc, { signal: controller.signal })
      .then(async (response) => {
        if (!response.ok) throw new Error("Transcript request failed")
        const cues = parseWebVtt(await response.text())
        if (cues.length === 0) throw new Error("Transcript is empty")
        transcriptRequestRef.current = { src: transcriptSrc, status: "done" }
        setTranscriptCues(cues)
        setTranscriptStatus("ready")
      })
      .catch((error) => {
        if (error instanceof DOMException && error.name === "AbortError") {
          if (transcriptRequestRef.current?.src === transcriptSrc) {
            transcriptRequestRef.current = null
          }
          return
        }
        transcriptRequestRef.current = { src: transcriptSrc, status: "done" }
        setTranscriptStatus("error")
      })
    return () => {
      controller.abort()
      if (
        transcriptRequestRef.current?.src === transcriptSrc &&
        transcriptRequestRef.current.status === "loading"
      ) {
        transcriptRequestRef.current = null
      }
    }
  }, [transcriptOpen, transcriptSrc])

  const clearResume = () => {
    window.localStorage.removeItem(resumeKey)
    setResumeSeconds(null)
  }

  const storeProgress = (detail: MediaTimeUpdateEvent["detail"]) => {
    const currentTime = detail.currentTime
    const duration = playerRef.current?.duration ?? 0
    for (const threshold of reachedVideoMilestones(currentTime, duration, milestonesRef.current)) {
      emitMilestone(threshold)
    }
    if (currentTime < 10 || (duration > 0 && duration - currentTime <= 15)) {
      if (duration > 0 && duration - currentTime <= 15) clearResume()
      return
    }
    const bucket = Math.floor(currentTime / 5)
    if (bucket === lastStoredBucket.current) return
    lastStoredBucket.current = bucket
    window.localStorage.setItem(
      resumeKey,
      JSON.stringify({ seconds: currentTime, updatedAt: Date.now() }),
    )
  }

  const seekTo = (seconds: number) => {
    const player = playerRef.current
    if (!player?.state.canSeek) return
    player.currentTime = seconds
    setResumeSeconds(null)
  }

  const continueFrom = (seconds: number) => {
    const player = playerRef.current
    if (!player?.state.canSeek) return
    clearResume()
    void continueVideoPlayback(player, seconds)
  }

  return (
    <div className="content-video-accessible">
      <div className="content-video-frame">
        <div
          className="content-video-controlled"
          data-provider={provider}
          data-player-state={status}
        >
          <CursareVideoPlayer
            ref={playerRef}
            className="content-video-player"
            src={src}
            provider={provider}
            title={title}
            ariaLabel={title}
            aria-describedby={helpId}
            viewType="video"
            streamType="on-demand"
            load="visible"
            posterLoad="visible"
            preload="metadata"
            playsInline
            autoPlay={false}
            storage={null}
            keyDisabled
            keyTarget="player"
            onCanPlay={() => {
              setStatus("ready")
              const duration = playerRef.current?.duration ?? 0
              if (resumeSeconds != null && duration > 0 && duration - resumeSeconds <= 15) {
                clearResume()
              }
              handleRef.current?.ready?.()
            }}
            onTimeUpdate={storeProgress}
            onPlay={() => {
              emitMilestone(0)
            }}
            onEnded={() => {
              clearResume()
              emitMilestone(100)
            }}
            onError={() => {
              setStatus("error")
              handleRef.current?.destroy?.()
            }}
            onKeyDownCapture={(event) => {
              const player = playerRef.current
              if (player) applyShortcut(event, player)
            }}
            tracks={tracks}
            translations={translations}
          />
          {resumeSeconds != null && status === "ready" ? (
            <div className="content-video-resume" role="status">
              <p className="content-video-resume-message">
                {resumePrompt(formatVideoTime(resumeSeconds))}
              </p>
              <div className="content-video-resume-actions">
                <Button
                  onPointerDown={(event) => event.stopPropagation()}
                  onClick={(event) => {
                    event.stopPropagation()
                    continueFrom(resumeSeconds)
                  }}
                >
                  {resumeAction}
                </Button>
                <Button
                  variant="secondary"
                  onPointerDown={(event) => event.stopPropagation()}
                  onClick={(event) => {
                    event.stopPropagation()
                    continueFrom(0)
                  }}
                >
                  {startOver}
                </Button>
              </div>
            </div>
          ) : null}
          {status === "loading" ? (
            <div className="content-video-status" role="status">
              {loadingLabel}
            </div>
          ) : null}
          {status === "error" ? (
            <div className="content-video-status is-error" role="alert">
              {failureLabel}
            </div>
          ) : null}
          <LearnerVisuallyHidden id={helpId}>{shortcutHelp}</LearnerVisuallyHidden>
        </div>
      </div>
      {transcriptTrack ? (
        <details
          className="content-video-transcript"
          onToggle={(event) => setTranscriptOpen(event.currentTarget.open)}
        >
          <summary>{transcriptLabel}</summary>
          <div className="content-video-transcript-panel">
            <Input
              type="search"
              value={transcriptQuery}
              onChange={(event) => setTranscriptQuery(event.target.value)}
              placeholder={transcriptSearchLabel}
              aria-label={transcriptSearchLabel}
            />
            {transcriptStatus === "loading" ? (
              <p className="content-video-transcript-state" role="status">
                {loadingLabel}
              </p>
            ) : transcriptStatus === "error" ? (
              <p className="content-video-transcript-state" role="alert">
                {transcriptFailureLabel}
              </p>
            ) : transcriptStatus === "ready" && visibleCues.length === 0 ? (
              <p className="content-video-transcript-state">{transcriptEmptyLabel}</p>
            ) : (
              <div className="content-video-transcript-cues">
                {visibleCues.map((cue) => (
                  <Button
                    type="button"
                    variant="ghost"
                    key={`${cue.start}:${cue.end}:${cue.text}`}
                    className="content-video-transcript-cue w-full justify-start text-left"
                    onClick={() => seekTo(cue.start)}
                  >
                    <time>{formatVideoTime(cue.start)}</time>
                    <span>{cue.text}</span>
                  </Button>
                ))}
              </div>
            )}
          </div>
        </details>
      ) : null}
    </div>
  )
}

