import { type ImgHTMLAttributes, useState } from "react"

export interface ContentCoverMediaProps
  extends Omit<ImgHTMLAttributes<HTMLImageElement>, "alt" | "className" | "src" | "style"> {
  src?: string | null
  alt?: string
  className?: string
  contentSlot?: string
  imageClassName?: string
