@media (min-width: 360px) {
  :where(
    .learner-course-shell,
    .learner-course-storefront,
    .content-editor[data-mode="reader"],
    [data-learner-family]
  ) {
    --learner-page-gutter: 1.25rem;
  }
}

@media (min-width: 640px) {
  :where(
    .learner-course-shell,
    .learner-course-storefront,
    .content-editor[data-mode="reader"],
    [data-learner-family]
  ) {
    --learner-page-gutter: 2rem;
    --learner-technical-padding: var(--learner-space-4);
    --learner-technical-toolbar-align: center;
    --learner-deck-track-gap: var(--learner-space-4);
    --learner-deck-track-padding: max(
      calc((var(--learner-space-24) + var(--learner-space-16)) / 2),
      calc((100cqi - var(--learner-measure-wide)) / 2)
    );
    --learner-deck-item-inline: min(
      calc(100cqi - var(--learner-space-24) - var(--learner-space-16)),
      var(--learner-measure-wide)
    );
    --learner-deck-slide-min: var(--learner-stage-min);
    --learner-deck-card-min-responsive: var(--learner-card-min);
    --learner-deck-item-padding: var(--learner-space-8);
    --learner-deck-controls-gap: var(--learner-space-3);
    --learner-deck-controls-padding: 0;
    --learner-certificate-ratio: 297 / 210;
    --learner-certificate-gap: var(--learner-space-6);
    --learner-certificate-padding: var(--learner-space-8);
    --learner-certificate-brand-align: center;
    --learner-certificate-cursare-inline: auto;
    --learner-certificate-details-columns: minmax(0, 1fr) minmax(0, 1.35fr) minmax(0, 0.8fr) auto;
    --learner-certificate-verification-align: end;
  }
}

@media (min-width: 1024px) {
  :where(
    .learner-course-shell,
    .learner-course-storefront,
    .content-editor[data-mode="reader"],
    [data-learner-family]
  ) {
    --learner-page-gutter: 3rem;
  }
}

@media (max-width: 30rem) {
  [data-learner-family="practice"] .content-question-navigation > [data-slot="button"] {
    flex: 1;
  }
}

:where(
    .learner-course-shell,
    .learner-course-storefront,
    .content-editor[data-mode="reader"],
    [data-learner-family]
  )
  :where(
    button:not([data-slot]),
    input:not([data-slot]),
    textarea:not([data-slot]),
    select:not([data-slot])
  ) {
  font-family: var(--learner-font-sans);
  font-size: var(--learner-ui-size);
  line-height: var(--learner-ui-line);
}

:where(
    .learner-course-shell,
    .learner-course-storefront,
    .content-editor[data-mode="reader"],
    [data-learner-family]
  )
  :where(button, a, input, select, textarea) {
  touch-action: manipulation;
}

:where(
    .learner-course-shell,
    .learner-course-storefront,
    .content-editor[data-mode="reader"],
    [data-learner-family]
  )
  :where(
    button:not([data-slot="button"]),
    a:not([data-slot="button"]),
    [role="button"],
    [role="option"]
  ) {
  min-block-size: var(--learner-control-hit);
}

[data-learner-measure="inline"] {
  inline-size: auto;
}

[data-learner-measure="prose"] {
  inline-size: min(100%, var(--learner-measure-prose));
}

[data-learner-measure="wide"] {
  inline-size: min(100%, var(--learner-measure-wide));
}

[data-learner-measure="media"] {
  inline-size: min(100%, var(--learner-measure-media));
}

[data-learner-measure="page"] {
  inline-size: 100%;
}

.learner-measure[data-learner-measure="page"] {
  padding-inline: var(--learner-page-gutter);
}

.learner-component {
  min-inline-size: 0;
}

.learner-component-header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: start;
  gap: var(--learner-space-3);
}

.learner-component-heading {
  display: grid;
  gap: var(--learner-space-1);
  min-inline-size: 0;
}

.learner-component-icon {
  display: inline-grid;
  inline-size: var(--learner-icon-component);
  block-size: var(--learner-icon-component);
  margin-block-start: calc((var(--learner-h3-line) - var(--learner-icon-component)) / 2);
  place-items: center;
}

.learner-component-icon > svg {
  inline-size: var(--learner-icon-component);
  block-size: var(--learner-icon-component);
  stroke-width: var(--learner-icon-stroke);
}

[data-learner-icon="inline"] > svg,
svg[data-learner-icon="inline"] {
  inline-size: var(--learner-icon-inline);
  block-size: var(--learner-icon-inline);
  stroke-width: var(--learner-icon-stroke);
}

[data-learner-icon="control"] > svg,
svg[data-learner-icon="control"] {
  inline-size: var(--learner-icon-control);
  block-size: var(--learner-icon-control);
  stroke-width: var(--learner-icon-stroke);
}

[data-learner-icon="component"] > svg,
svg[data-learner-icon="component"] {
  inline-size: var(--learner-icon-component);
  block-size: var(--learner-icon-component);
  stroke-width: var(--learner-icon-stroke);
}

[data-learner-icon="hero"] > svg,
svg[data-learner-icon="hero"] {
  inline-size: var(--learner-icon-hero);
  block-size: var(--learner-icon-hero);
  stroke-width: var(--learner-icon-stroke);
}

.learner-component-title {
  font-family: var(--learner-font-sans);
  font-weight: 600;
  font-size: var(--learner-h3-size);
  line-height: var(--learner-h3-line);
  overflow-wrap: anywhere;
}

.learner-block-shell {
  display: grid;
  min-inline-size: 0;
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.learner-block-shell-header {
  padding: 0;
}

.learner-block-shell-body {
  min-inline-size: 0;
}

.learner-component-description {
  max-inline-size: var(--learner-measure-prose);
  color: var(--muted-foreground);
  font-family: var(--learner-font-sans);
  font-size: var(--learner-ui-size);
  line-height: var(--learner-ui-line);
  overflow-wrap: anywhere;
}

.learner-component-metadata,
.learner-component-progress-label {
  color: var(--muted-foreground);
  font-family: var(--learner-font-sans);
  font-size: var(--learner-meta-size);
  line-height: var(--learner-meta-line);
}

.learner-component-instruction {
  max-inline-size: var(--learner-measure-prose);
  color: var(--muted-foreground);
  font-family: var(--learner-font-sans);
  font-size: var(--learner-ui-size);
  line-height: var(--learner-ui-line);
}

.learner-component-actions,
.learner-component-action-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--learner-space-2);
}

.learner-component-progress {
  display: grid;
  gap: var(--learner-space-2);
}

.learner-component-progress-track {
  block-size: var(--learner-space-1);
  overflow: hidden;
  border-radius: var(--learner-radius-pill);
  background: color-mix(in oklab, var(--foreground) 10%, transparent);
}

.learner-component-progress-track > span {
  display: block;
  inline-size: var(--learner-progress, 0%);
  block-size: 100%;
  border-radius: inherit;
  background: var(--course-accent);
  transition: inline-size var(--learner-motion-trace) var(--learner-motion-ease);
}

.learner-component-feedback,
.learner-component-empty {
  font-family: var(--learner-font-sans);
  font-size: var(--learner-ui-size);
  line-height: var(--learner-ui-line);
}

[data-learner-theme-role="source-owned"] :where(img, svg) {
  filter: none;
}

[data-learner-family="journey"] {
  inline-size: 100%;
}

.learner-course-card {
  border: 0;
  border-radius: var(--learner-radius-surface);
  background: var(--learner-course-soft);
  box-shadow: none;
}

.learner-course-card:where(:hover, :focus-within) {
  background: var(--learner-course-hover);
}

.learner-course-card-cover {
  border-radius: var(--learner-radius-control);
}

.learner-course-empty {
  background: var(--learner-course-soft);
}

.learner-storefront-hero {
  display: grid;
  gap: var(--learner-space-6);
}

.learner-storefront-profile {
  position: relative;
  display: grid;
  border-radius: var(--learner-radius-media);
  background: var(--learner-course-soft);
}

.learner-storefront-cover {
  border-radius: var(--learner-radius-media);
}

.learner-continuation {
  position: relative;
  border-radius: var(--learner-radius-media);
  background: var(--learner-course-soft);
  color: var(--foreground);
}

.learner-continuation::before {
  position: absolute;
  z-index: 1;
  inset-block: 0;
  inset-inline-start: 0;
  inline-size: var(--learner-space-1);
  border-radius: var(--learner-radius-pill);
  background: var(--course-accent);
  content: "";
}

.learner-continuation-media {
  background: var(--learner-course-selected);
}

.learner-continuation-media > img {
  opacity: 0.82;
}

.learner-continuation-media-fade {
  background: var(--learner-course-fade);
}

.learner-storefront-course,
.learner-storefront-recommendation {
  border-radius: var(--learner-radius-media);
  background: transparent;
  transition: background-color var(--learner-motion-focus) var(--learner-motion-ease);
}

.learner-storefront-course:where(:hover, :focus-visible),
.learner-storefront-recommendation:where(:hover, :focus-visible) {
  background: var(--learner-course-hover);
}

.learner-storefront-course:focus-visible,
.learner-storefront-recommendation:focus-visible,
.learner-continuation:focus-visible {
  outline: var(--learner-focus-width) solid var(--ring);
  outline-offset: var(--learner-focus-offset);
}

.learner-upcoming-cohort,
.learner-storefront-empty {
  border-radius: var(--learner-radius-surface);
  background: var(--learner-course-soft);
}

.learner-topic-active,
.learner-topic-idle {
  transition:
    background-color var(--learner-motion-focus) var(--learner-motion-ease),
    color var(--learner-motion-focus) var(--learner-motion-ease);
}

.learner-topic-active {
  background: var(--learner-course-selected);
  color: var(--foreground);
}

.learner-topic-idle {
  background: var(--learner-course-soft);
}

.learner-topic-idle:hover {
  background: var(--learner-course-hover);
}

.learner-storefront-footer {
  border-block-start: var(--learner-line-width) solid var(--border);
}

.learner-milestone {
  border-radius: var(--learner-radius-surface);
  background: var(--learner-success-soft);
}

.learner-course-home {
  padding: var(--learner-space-12) var(--learner-page-gutter);
}

.learner-course-home-hero {
  gap: var(--learner-space-8);
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

.learner-course-home-cover {
  inline-size: 100%;
  min-inline-size: 0;
  overflow: hidden;
  border-radius: var(--learner-radius-media);
}

.learner-course-home-copy {
  padding: var(--learner-space-6);
}

.learner-course-home-copy > h1 {
  font-family: var(--learner-font-heading);
  font-size: var(--learner-h1-size);
  line-height: var(--learner-h1-line);
  letter-spacing: var(--learner-display-tracking);
}

.learner-course-home-description {
  color: var(--muted-foreground);
  font-size: var(--learner-body-size);
  line-height: var(--learner-body-line);
}

.learner-course-home-grid {
  gap: var(--learner-space-12);
  padding-block: var(--learner-space-12);
}

.learner-course-home-cohort {
  padding: var(--learner-space-6);
  border: 0;
  border-radius: var(--learner-radius-surface);
  background: var(--learner-course-soft);
  box-shadow: none;
}

.learner-journey-list {
  border: 0;
}

.learner-journey-list > li {
  border: 0;
}

.learner-journey-list > li + li {
  border-block-start: var(--learner-line-width) solid var(--border);
}

.learner-journey-item {
  min-block-size: var(--learner-control-hit);
  gap: var(--learner-space-3);
  padding: var(--learner-space-4) var(--learner-space-3);
}

.learner-journey-icon {
  inline-size: var(--learner-control-hit);
  block-size: var(--learner-control-hit);
  border: 0;
  border-radius: var(--learner-radius-pill);
  background: var(--learner-course-soft);
}

.learner-journey-icon > svg {
  inline-size: var(--learner-icon-component);
  block-size: var(--learner-icon-component);
  stroke-width: var(--learner-icon-stroke);
}

[data-journey-state="completed"] .learner-journey-icon {
  background: var(--learner-success-soft);
  color: var(--learner-success-ink);
}

[data-journey-state="current"] .learner-journey-icon {
  border: 0;
  background: var(--course-accent);
  color: var(--course-accent-ink);
}

[data-journey-state="locked"] .learner-journey-item {
  color: var(--muted-foreground);
}

[data-learner-family="journey"] > [data-learner-identity] {
  display: grid;
  gap: var(--learner-space-3);
}

.learner-certificate {
  position: relative;
  isolation: isolate;
  display: grid;
  aspect-ratio: var(--learner-certificate-ratio);
  overflow: hidden;
  align-content: space-between;
  gap: var(--learner-certificate-gap);
  padding: var(--learner-certificate-padding);
  border: var(--learner-line-width) solid var(--border);
  border-radius: var(--learner-radius-surface);
  background: var(--learner-deck-card);
  box-shadow: none;
  color: var(--foreground);
  text-align: center;
}

.learner-certificate-pattern {
  position: absolute;
  z-index: -1;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  color: var(--muted-foreground);
  opacity: 0.1;
}

.learner-certificate-pattern path,
.learner-certificate-pattern circle {
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
}

.learner-certificate-trace {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: var(--learner-space-2);
  inline-size: 100%;
}

.learner-certificate-trace > span {
  block-size: var(--learner-space-1);
  border-radius: var(--learner-radius-pill);
  background: color-mix(in oklab, var(--foreground) 52%, transparent);
  transform-origin: left;
}

.learner-certificate-trace > span:nth-child(2) {
  background: color-mix(in oklab, var(--foreground) 34%, transparent);
}

.learner-certificate-trace > span:nth-child(3) {
  background: color-mix(in oklab, var(--foreground) 20%, transparent);
}

.learner-certificate-brands {
  display: flex;
  flex-wrap: wrap;
  align-items: var(--learner-certificate-brand-align);
  justify-content: space-between;
  gap: var(--learner-space-4);
  text-align: start;
}

.learner-certificate-cursare,
.learner-certificate-organization {
  display: inline-flex;
  min-block-size: var(--learner-control-hit);
  align-items: center;
  gap: var(--learner-space-2);
  font-size: var(--learner-ui-size);
  line-height: var(--learner-ui-line);
}

.learner-certificate-cursare {
  inline-size: var(--learner-certificate-cursare-inline);
  color: var(--muted-foreground);
  font-size: var(--learner-label-size);
  line-height: var(--learner-label-line);
}

.learner-certificate-cursare > svg {
  inline-size: var(--learner-space-6);
  block-size: var(--learner-space-6);
}

.learner-certificate-organization > img,
.learner-certificate-organization-fallback {
  display: grid;
  inline-size: var(--learner-control-hit);
  block-size: var(--learner-control-hit);
  place-items: center;
  border-radius: var(--learner-radius-control);
  object-fit: cover;
}

.learner-certificate-organization {
  font-weight: 600;
}

.learner-certificate-content {
  display: grid;
  gap: var(--learner-space-3);
  inline-size: min(100%, var(--learner-measure-prose));
  margin-inline: auto;
}

.learner-certificate-seal {
  display: grid;
  inline-size: var(--learner-space-16);
  block-size: var(--learner-space-16);
  margin-inline: auto;
  place-items: center;
  border-radius: var(--learner-radius-pill);
  background: var(--learner-course-soft);
  color: var(--foreground);
}

.learner-certificate-seal > svg {
  inline-size: var(--learner-space-8);
  block-size: var(--learner-space-8);
  stroke-width: var(--learner-icon-stroke);
}

.learner-certificate-eyebrow {
  color: var(--foreground);
  font-weight: 600;
  font-size: var(--learner-label-size);
  line-height: var(--learner-label-line);
  letter-spacing: normal;
  text-transform: none;
}

.learner-certificate-context,
.learner-certificate-course > p,
.learner-certificate-details span {
  color: var(--muted-foreground);
  font-size: var(--learner-meta-size);
  line-height: var(--learner-meta-line);
}

.learner-certificate-content > h1 {
  max-inline-size: var(--learner-measure-prose);
  margin-inline: auto;
  font-family: var(--learner-font-heading);
  font-size: var(--learner-display-size);
  line-height: var(--learner-display-line);
  letter-spacing: var(--learner-display-tracking);
  text-wrap: balance;
}

.learner-certificate-course {
  display: grid;
  gap: var(--learner-space-2);
}

.learner-certificate-course > h2 {
  max-inline-size: var(--learner-measure-prose);
  margin-inline: auto;
  font-family: var(--learner-font-heading);
  font-size: var(--learner-h1-size);
  line-height: var(--learner-h1-line);
  text-wrap: balance;
}

.learner-certificate-details {
  display: grid;
  grid-template-columns: var(--learner-certificate-details-columns);
  gap: var(--learner-space-4);
  inline-size: min(100%, var(--learner-measure-wide));
  margin-inline: auto;
  padding-block-start: var(--learner-space-6);
  border-block-start: var(--learner-line-width) solid
    color-mix(in oklab, var(--border) 64%, transparent);
  text-align: start;
}

.learner-certificate-details > div {
  display: grid;
  gap: var(--learner-space-1);
}

.learner-certificate-details strong {
  overflow-wrap: anywhere;
  font-size: var(--learner-ui-size);
  line-height: var(--learner-ui-line);
}

.learner-certificate-issuer {
  display: flex;
  align-items: center;
  gap: var(--learner-space-2);
}

.learner-certificate-issuer > img,
.learner-certificate-issuer-mark {
  display: grid;
  flex: none;
  inline-size: var(--learner-space-8);
  block-size: var(--learner-space-8);
  place-items: center;
  border-radius: var(--learner-radius-control);
  background: var(--learner-course-soft);
  object-fit: cover;
  font-size: var(--learner-meta-size);
}

.learner-certificate-verification > a {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: var(--learner-space-2);
  color: inherit;
  text-decoration: none;
}

.learner-certificate-verification {
  justify-self: var(--learner-certificate-verification-align);
}

.learner-certificate-verification img {
  inline-size: var(--learner-space-16);
  block-size: var(--learner-space-16);
  border: var(--learner-line-width) solid var(--border);
  border-radius: var(--learner-radius-control);
  background: var(--learner-credential-code-background);
}

.learner-certificate-verification a:hover > span {
  color: var(--foreground);
}

.learner-certificate-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--learner-space-3);
}

@media (prefers-reduced-motion: reduce) {
  .learner-certificate-trace > span {
    animation: none;
  }
}

@media print {
  @page {
    size: A4 landscape;
    margin: 0;
  }

  .learner-certificate {
    break-inside: avoid;
    inline-size: 297mm;
    block-size: 210mm;
    align-content: center;
    padding: 24mm;
    border-radius: 0;
    box-shadow: none;
    print-color-adjust: exact;
  }

  .learner-certificate-trace > span {
    animation: none;
  }
}

[data-learner-family="media"] {
  position: relative;
  display: grid;
  gap: var(--learner-space-3);
  margin-block: var(--learner-space-8);
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

[data-learner-family="media"] > .content-block-card {
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

[data-learner-family="media"] .learner-component-header {
  position: static;
  inset: auto;
  color: var(--foreground);
}

[data-learner-component="runtime.media.audio"] {
  gap: var(--learner-space-4);
  padding: 0;
}

[data-learner-component="runtime.media.audio"] .learner-component-header {
  position: static;
  inset: auto;
}

[data-learner-component="runtime.media.image"] {
  display: grid;
  gap: var(--learner-space-3);
  overflow: visible;
  border-radius: 0;
  background: transparent;
}

[data-learner-component="runtime.media.image"] .learner-component-header {
  position: static;
  inset: auto;
  inline-size: var(--learner-image-width, 100%);
  max-inline-size: 100%;
  margin-inline: auto;
}

[data-learner-component="runtime.media.video"] {
  overflow: visible;
  border-radius: 0;
  background: transparent;
}

[data-learner-component="runtime.media.video"] .learner-block-shell-header {
  position: static;
  inset: auto;
}

[data-learner-component="runtime.media.video"] .content-video-controlled {
  position: relative;
}

[data-learner-component="runtime.media.audio"] .content-audio-body {
  min-inline-size: 0;
  padding: 0;
}

[data-learner-component="runtime.media.audio"] .content-audio-player {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--learner-space-3);
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

[data-learner-component="runtime.media.audio"] .content-audio-player > audio {
  display: none;
}

[data-learner-component="runtime.media.audio"] .content-audio-volume {
  display: none;
}

[data-learner-component="runtime.media.audio"] .content-audio-seek {
  inline-size: 100%;
  min-block-size: var(--learner-control-hit);
  accent-color: var(--foreground);
}

[data-learner-component="runtime.media.audio"] .content-audio-time {
  color: var(--muted-foreground);
  font-size: var(--learner-meta-size);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

[data-learner-family="media"] :where(img, video, iframe) {
  display: block;
  inline-size: 100%;
  block-size: auto;
}

/* An embed iframe carries no intrinsic size, so block-size:auto alone collapses
   it to the small default iframe height. A 16:9 box fills the column at a usable
   height — the aspect-ratio drives block-size from the full inline-size above. */
.content-embed-frame {
  aspect-ratio: 16 / 9;
  border: 0;
  border-radius: var(--learner-radius-media);
}

[data-learner-component="runtime.media.image"] .content-image-frame {
  inline-size: var(--learner-image-width, 100%);
  max-inline-size: 100%;
  overflow: clip;
  margin-inline: auto;
  border-radius: var(--learner-radius-media);
}

[data-learner-family="media"] :where(.content-video-reader, .content-video-frame) {
  overflow: clip;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

[data-learner-component="runtime.media.video"] .content-video-status {
  position: absolute;
  z-index: 1;
  inset: 0;
  display: grid;
  min-block-size: 0;
  place-items: center;
  padding: var(--learner-space-8);
  background: color-mix(in oklab, var(--background) 12%, transparent);
  color: var(--muted-foreground);
}

[data-learner-family="media"] :where(.content-video-status.is-error, [role="alert"]) {
  background: var(--learner-danger-soft);
  color: var(--learner-danger-ink);
}

[data-learner-family="media"] :where(.content-audio-body, .content-embed-caption) {
  padding: 0;
}

:where(
  .learner-course-shell,
  .learner-course-storefront,
  .content-editor[data-mode="reader"],
  [data-learner-family]
) {
  --learner-motion-focus: 120ms;
  --learner-motion-reveal: 200ms;
  --learner-motion-trace: 280ms;
  --learner-motion-milestone: 700ms;
  --learner-motion-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
}

[data-learner-effect="focus"] {
  transition:
    background-color var(--learner-motion-focus) var(--learner-motion-ease),
    color var(--learner-motion-focus) var(--learner-motion-ease),
    outline-color var(--learner-motion-focus) var(--learner-motion-ease);
}

[data-learner-effect="lift"] {
  transition:
    transform var(--learner-motion-focus) var(--learner-motion-ease),
    box-shadow var(--learner-motion-reveal) var(--learner-motion-ease);
}

[data-learner-effect="lift"][data-active="true"] {
  transform: translateY(-0.25rem) scale(1.015);
  box-shadow: var(--learner-elevation-lift);
}

[data-learner-effect="lift"]:where(:hover, :focus-within) {
  transform: translateY(-0.25rem) scale(1.015);
  box-shadow: var(--learner-elevation-lift);
}

[data-learner-effect="reveal"] {
  animation: learner-reveal var(--learner-motion-reveal) var(--learner-motion-ease) both;
}

[data-learner-effect="trace"] {
  transition: inline-size var(--learner-motion-trace) var(--learner-motion-ease);
}

[data-learner-effect="trace"] > [data-learner-trace-segment] {
  animation: learner-trace var(--learner-motion-trace) var(--learner-motion-ease) both;
}

[data-learner-effect="trace"] > [data-learner-trace-segment]:nth-child(2) {
  animation-delay: var(--learner-motion-focus);
}

[data-learner-effect="trace"] > [data-learner-trace-segment]:nth-child(3) {
  animation-delay: var(--learner-motion-reveal);
}

[data-learner-effect="milestone"] {
  animation: learner-milestone var(--learner-motion-milestone) var(--learner-motion-ease) both;
}

@keyframes learner-reveal {
  from {
    opacity: 0;
    transform: translateY(0.5rem);
  }
}

@keyframes learner-milestone {
  0% {
    opacity: 0;
    transform: translateY(1rem) scale(0.985);
  }
  70% {
    opacity: 1;
  }
}

@keyframes learner-trace {
  from {
    opacity: 0;
    transform: scaleX(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-learner-effect] {
    animation: learner-fade 80ms linear both;
    transform: none;
    transition: none;
  }

  @keyframes learner-fade {
    from {
      opacity: 0;
    }
  }
}

[data-learner-family="navigation"] {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--learner-space-4);
  margin-block: var(--learner-space-8);
  padding-block: 0;
}

[data-learner-component="runtime.navigation.file"],
[data-learner-component="runtime.navigation.reference"] {
  display: block;
  max-inline-size: 100%;
  padding-block: 0;
}

[data-learner-component="runtime.navigation.file"] .learner-component-header {
  align-items: center;
}

[data-learner-component="runtime.navigation.file"] .learner-component-actions {
  align-self: center;
}

[data-learner-component="runtime.navigation.file"] .content-file-card {
  display: grid;
  min-block-size: var(--learner-control-hit);
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--learner-space-3);
  padding: var(--learner-space-3) var(--learner-space-4);
  border: 0;
  border-radius: var(--learner-radius-control);
