  margin-inline-start: calc(var(--learner-icon-component) + var(--learner-space-3));
  padding-inline: 0;
}

[data-learner-component="runtime.navigation.reference"].content-reference-reader {
  display: block;
  min-block-size: var(--learner-control-hit);
  padding: var(--learner-space-2) 0;
  border: 0;
  border-radius: var(--learner-radius-control);
  color: inherit;
  text-decoration: none;
  box-shadow: none;
}

[data-learner-component="runtime.navigation.file"] .content-file-card:hover {
  background: var(--learner-course-hover);
}

[data-learner-component="runtime.navigation.file"] .content-file-icon {
  display: inline-grid;
  inline-size: var(--learner-control-hit);
  block-size: var(--learner-control-hit);
  place-items: center;
  color: var(--muted-foreground);
}

[data-learner-component="runtime.navigation.reference"] .content-reference-trailing {
  display: inline-grid;
  inline-size: var(--learner-control-hit);
  block-size: var(--learner-control-hit);
  place-items: center;
  color: var(--muted-foreground);
}

[data-learner-component="runtime.navigation.file"] .content-file-action {
  display: inline-flex;
  min-block-size: var(--learner-control-hit);
  align-items: center;
