}

[data-learner-component="runtime.navigation.file"] .content-file-text {
  display: grid;
  min-inline-size: 0;
  gap: var(--learner-space-1);
}

[data-learner-component="runtime.navigation.file"] .content-file-name {
  overflow: hidden;
  font-size: var(--learner-ui-size);
  font-weight: 600;
  line-height: var(--learner-ui-line);
  text-overflow: ellipsis;
