}

[data-learner-component="runtime.navigation.file"] .content-file-meta,
[data-learner-component="runtime.navigation.reference"] .content-reference-meta {
  margin: 0;
  color: var(--muted-foreground);
  font-size: var(--learner-meta-size);
  line-height: var(--learner-meta-line);
}

[data-learner-component="runtime.navigation.reference"] .content-reference-header {
  align-items: start;
}

[data-learner-component="runtime.navigation.reference"]
  .content-reference-header
  .learner-component-actions {
  align-self: center;
}

[data-learner-component="runtime.navigation.reference"] .content-reference-meta {
  display: flex;
  min-inline-size: 0;
  align-items: center;
  gap: var(--learner-space-2);
}

[data-learner-component="runtime.navigation.reference"] .content-reference-slug {
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-learner-component="runtime.navigation.reference"] .content-reference-release {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-learner-component="runtime.navigation.reference"].content-reference-reader[data-done] {
  background: transparent;
