[data-learner-component="runtime.navigation.reference"].content-reference-reader[data-disabled] {
  background: transparent;
  opacity: 0.64;
}

[data-learner-component="runtime.navigation.reference"] .content-reference-done {
  color: var(--learner-success-ink);
}

.learner-continue:not([data-course-complete="true"]) {
  border-radius: var(--learner-radius-surface);
  background: var(--learner-course-soft);
}

[data-learner-family="practice"] {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-inline-size: 0;
  inline-size: 100%;
  max-inline-size: 100%;
  gap: var(--learner-space-4);
  margin-block: var(--learner-space-8);
