  font-family: var(--learner-font-sans);
  font-size: var(--learner-ui-size);
  line-height: var(--learner-ui-line);
}

/* The question sits on a faint neutral surface so it reads as a distinct
   (shadowless) panel — separated from transparent code blocks and the reader
   beneath it. Its inner card (the graded stage) stays flat on top. */
.content-question {
  background: var(--learner-neutral-surface);
}

[data-learner-component="runtime.practice.poll"] {
  gap: var(--learner-space-4);
  padding: 0;
  border-radius: 0;
  background: transparent;
