  border: var(--learner-line-width) solid var(--muted-foreground);
  border-radius: var(--learner-radius-pill);
  background: transparent;
  box-shadow: none;
  content: "";
}

[data-learner-component="runtime.practice.poll"] .content-poll-choice:not(:disabled):hover {
  background: var(--learner-course-hover);
